import React from "react";

const InfoSection = () => {
  const cards = [
    { title: "What is Churn?", text: "Churn prediction identifies customers likely to leave a service." },
    { title: "Dataset Used", text: "Includes customer demographics, tenure, charges, contract type, etc." },
    { title: "Algorithms", text: "Logistic Regression, Random Forest, XGBoost, SVM, Neural Networks." },
    { title: "Benefits", text: "Reduced customer loss, improved targeting, business insights." },
    { title: "Use Cases", text: "Telecom, SaaS, Banking, OTT platforms." }
  ];

  return (
    <div style={{ marginTop: "30px" }}>
      <h2 style={{ fontSize: "28px", marginBottom: "20px" }}>Churn Prediction Overview</h2>
      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
        gap: "20px"
      }}>
        {cards.map((c, i) => (
          <div key={i} style={{
            background: "white",
            padding: "20px",
            borderRadius: "10px",
            boxShadow: "0 2px 6px rgba(0,0,0,0.2)"
          }}>
            <h3>{c.title}</h3>
            <p>{c.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default InfoSection;
